"""Seed content for the ARENA. Upserted by slug on startup; admin edits in the DB are never overwritten."""


def Q(slug, category, difficulty, prompt, options, answer, explanation, code="", lang="", set_key=None):
    return {"slug": slug, "category": category, "set": set_key, "difficulty": difficulty, "prompt": prompt,
            "code": code, "code_lang": lang, "options": options, "answer_index": answer, "explanation": explanation}


